"""Render the Gate 8 receipt without hand-transcribing performance numbers."""
import json
from pathlib import Path


def render(data):
    summary = data["summaries"]
    frozen = summary["frozen"]
    total = sum(s["test_images"] for s in data["specimens"])
    rows = ["# Gate 8 — retrieval access results", "",
            "Generated by `report_access_results.py` from "
            "[the numerical receipt](results/gate8_retrieval_access.json). "
            "See [protocol and interpretation](RETRIEVAL_ACCESS.md).", "",
            f"Seeds: {data['protocol']['seeds']}. {total} held-out evaluations across "
            "three resampled splits of the same dataset; these are not independent datasets. "
            "Percentages are means over splits. Small differences are descriptive, "
            "without a claim of statistical superiority.", "",
            "## Access with material frozen", "",
            "| Available cue / policy | Accuracy | Mean cue queries |",
            "| --- | ---: | ---: |"]
    for label, key, cost in (
        ("Full image", "full_accuracy_before", 1.),
        ("Upper half", "upper_accuracy_before", 1.),
        ("Lower half", "lower_accuracy_before", 1.),
        ("Always combine both halves", "two_cue_accuracy_before", 2.),
        ("Ask lower only if uncertain about upper", "policy_accuracy_before", frozen["policy_mean_queries_before"]),
        ("Blank upper input; same confidence policy", "blocked_upper_policy_accuracy_before", frozen["blocked_upper_policy_mean_queries_before"]),
    ):
        rows.append(f"| {label} | {100*frozen[key]:.2f}% | {cost:.3f} |")
    rows += ["", f"The first response is wrong and the policy stops in "
             f"{100*frozen['confident_wrong_stop_fraction_before']:.2f}% of evaluations. "
             f"In {100*frozen['alternate_cue_rescue_opportunity_before']:.2f}%, upper is wrong "
             "while lower alone is correct. That latter number is an evaluator-only "
             "opportunity, not an achieved retrieval policy.", "",
             "## Adaptation and its measurement cost", "",
             "All adaptive methods may use 12 attempts and 45,000 scalar callbacks. "
             "A new-task callback evaluates 64 examples, so example evaluations are "
             "also counted. Baseline selection and held-out evaluation are separate.", "",
             "| Method | New contrast accuracy | Full cue | Upper cue | Lower cue | Scalar calls | Example evaluations | Final adjustable values |",
             "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |"]
    for method, r in summary.items():
        rows.append(f"| `{method}` | {100*r['changed_accuracy_after']:.2f}% | "
                    f"{100*r['full_accuracy_after']:.2f}% | {100*r['upper_accuracy_after']:.2f}% | "
                    f"{100*r['lower_accuracy_after']:.2f}% | {r['scalar_calls']:.0f} | "
                    f"{r['model_example_evaluations']:.0f} | {r['final_adaptive_parameters']:.0f} |")
    rows += ["", "## Individual access losses concealed by averages", "",
             "These counts require that the full cue was correct both before and after "
             "adaptation, and that a partial cue changed from correct to incorrect. "
             "Counts are held-out evaluations, not distinct memories or people.", "",
             "| Method | Upper route lost | Lower route lost | Lower still correct when upper lost |",
             "| --- | ---: | ---: | ---: |"]
    for method, r in summary.items():
        counts = [round(total*r[k]) for k in (
            "upper_route_lost_while_full_correct", "lower_route_lost_while_full_correct",
            "alternate_still_correct_after_upper_lost")]
        rows.append(f"| `{method}` | {counts[0]} | {counts[1]} | {counts[2]} |")
    rows += ["", "## Tradeoffs and negative outcomes", "",
             "- Every protected method met its retained-bank contract. That did not "
             "prevent all unseen partial-cue failures.",
             "- Full and mixed margin banks behaved like unprotected adaptation here. "
             "Their limits did not constrain this task enough to establish a benefit.",
             "- The boundary bank lost fewer individual cue routes, while completing "
             "less of the requested objective change. This is a tradeoff at unequal "
             "progress, not proof of better protection at matched learning.",
             f"- Growth was triggered {summary['grow_mixed']['growth_events']} times. "
             "The growing condition completed its task in existing capacity. The "
             "larger control adds measurement cost without improving mean contrast "
             "accuracy in this receipt. Growth benefit remains unestablished.",
             "- Neither the calibration bank nor the confidence policy sees held-out "
             "labels. The experimenter uses those labels to score all outcomes.", "",
             "## Per-seed new-task progress", "",
             "| Seed | Method | Objective improvement | Requested improvement | Final status |",
             "| --- | --- | ---: | ---: | --- |"]
    for specimen in data["specimens"]:
        for r in specimen["runs"]:
            last = r["trajectory"][-1]["status"] if r["trajectory"] else "frozen"
            rows.append(f"| {r['seed']} | `{r['method']}` | "
                        f"{r['objective_after']-r['objective_before']:.6f} | "
                        f"{r['target']-r['objective_before']:.6f} | `{last}` |")
    rows += ["", "Engineering checks: " + ", ".join(
        f"`{key}={value}`" for key,value in data["checks"].items()) + ".", ""]
    return "\n".join(rows)


if __name__ == "__main__":
    root = Path(__file__).resolve().parent
    data = json.loads((root/"results/gate8_retrieval_access.json").read_text())
    (root/"ACCESS_RESULTS.md").write_text(render(data))
